import{t as e}from"./api-7M9YWvHU.js";var t={async getPublicProducts(t){return(await e.get(`/store/products`,{params:t})).data},async getPublicProductBySlug(t){return(await e.get(`/store/products/${t}`)).data.data},async getCart(){return(await e.get(`/store/cart`)).data.data},async addToCart(t,n,r=1){return(await e.post(`/store/cart/items`,{product_id:t,variant_id:n,quantity:r})).data.data},async updateCartItem(t,n){return(await e.patch(`/store/cart/items/${t}`,{quantity:n})).data.data},async removeCartItem(t){return(await e.delete(`/store/cart/items/${t}`)).data.data},async checkout(t){return(await e.post(`/store/checkout`,t)).data.data},async getMyOrders(){return(await e.get(`/store/orders`)).data},async getMyOrder(t){return(await e.get(`/store/orders/${t}`)).data.data},async getAdminProducts(t){return(await e.get(`/store-admin/products`,{params:t})).data},async createAdminProduct(t){return(await e.post(`/store-admin/products`,t)).data.data},async updateAdminProduct(t,n){return(await e.put(`/store-admin/products/${t}`,n)).data.data},async deleteAdminProduct(t){await e.delete(`/store-admin/products/${t}`)},async getAdminInventory(t){return(await e.get(`/store-admin/inventory`,{params:t})).data},async adjustInventory(t){await e.post(`/store-admin/inventory/adjust`,t)},async getAdminOrders(t){return(await e.get(`/store-admin/orders`,{params:t})).data},async updateFulfillmentStatus(t,n){return(await e.patch(`/store-admin/orders/${t}/fulfillment`,{fulfillment_status:n})).data.data},async refundAdminOrder(t,n){return(await e.post(`/store-admin/orders/${t}/refund`,{reason:n})).data.data}};export{t};